/**
 * [FEAT-20260822-BCASTTRIGGER] Who started this run.
 * ===========================================================================
 * A pure type + pure factories. No database, no I/O, no clock.
 *
 * BOTH SOURCES ARE REAL WORK, not one now and one someday: the admin's button
 * and the scheduler (`schedule` date + next round) are both in scope. What is
 * NOT in scope is catch-up for rounds that were MISSED while the process was
 * down — see `mustRecheckCeiling` and the note below. (เจ้าของ 22/08)
 *
 * ⚠️ `runId` is generated by the CALLER so this file stays free of randomness
 *    and needs no stubbing in tests. `retry-key.ts` says why it must be stable
 *    for the whole run.
 *
 * revert: delete this file with the rest of `broadcast-send/`.
 */

export type RunTriggerSource = 'manual' | 'scheduler';

export interface RunTrigger {
  readonly source: RunTriggerSource;
  /** Stable for the whole run; part of every chunk's retry key. */
  readonly runId: string;
  /** Who pressed it. Absent for `scheduler`, which nobody presses. */
  readonly userId?: string;
  readonly userName?: string;
}

export function manualTrigger(
  runId: string,
  userId?: string,
  userName?: string,
): RunTrigger {
  return { source: 'manual', runId, userId, userName };
}

export function schedulerTrigger(runId: string): RunTrigger {
  return { source: 'scheduler', runId };
}

/**
 * Must the ceiling be re-checked before this run starts?
 *
 * 🔴 ALWAYS. This used to answer `true` only for scheduled runs, on the grounds
 * that a manual run had just been validated by the form — review showed that
 * reasoning does not hold:
 *   · the audience is selected LIVE, so it can grow between the form and the
 *     send, and a big campaign is often started minutes after it is saved
 *   · the runner can be reached without the form at all (a retry, an internal
 *     caller, a future route that forgets the check)
 * The check is one count against an index we already query. Skipping it buys
 * nothing and costs the guarantee at §PH.12.2 that an oversized run is refused
 * before anybody is messaged. ตรวจทุกครั้ง ไม่ว่าใครสั่ง.
 *
 * The parameter stays because the DECISION differs by source even though the
 * check does not: a scheduled run that fails may switch itself off (D55), while
 * a manual one simply reports back to the person standing there.
 */
export function mustRecheckCeiling(_trigger: RunTrigger): boolean {
  void _trigger;
  return true;
}

/**
 * ⚠️ NO CATCH-UP, ON PURPOSE (เจ้าของ 22/08: "พวกตกหล่น ยังไม่ต้อง").
 *
 * If the process was down when a round was due, that round is simply gone. The
 * next `next_run_at` is computed FORWARD from now, so a job that missed three
 * rounds fires once at its next real slot rather than three times in a row.
 * ⇒ nothing here replays anything, and there is deliberately no `grace_minutes`.
 * ⇒ a customer can never receive a burst because the server restarted.
 *
 * The day catch-up IS wanted, it is a new decision with its own rules — not a
 * tweak to this constant. วันที่อยากได้ค่อยตัดสินใหม่ ไม่ใช่มาแก้ค่าตรงนี้.
 */
export const CATCH_UP_MISSED_ROUNDS = false;
